#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""PASQAL exact response-fibre Krawczyk audit v1.2 — standalone Colab edition.

This version uses a frozen, descending interval-radius schedule independently
for every path. It never reads finite-error performance during conditioning.
Every attempted radius is written to the certificate, and only 12/12 strict
Krawczyk inclusions produce the full supported status.

Numerical precheck:
    %run /content/pasqal_L4_exact_fibre_krawczyk_standalone_colab_v1_2.py --numeric-only

Formal 12-path audit:
    %run /content/pasqal_L4_exact_fibre_krawczyk_standalone_colab_v1_2.py
"""
from __future__ import annotations
import base64
import gzip
import sys
import types

_EMBEDDED = {'_kraw_main': '',
 'pasqal_two_atom_matched_fibre_test': '',
 'pasqal_two_atom_q2_prospective_ranking': ''} 


def _source(key: str) -> bytes:
    return gzip.decompress(base64.b64decode(_EMBEDDED[key]))


def _install(name: str) -> None:
    module = types.ModuleType(name)
    module.__file__ = f"<embedded:{name}>"
    module.__package__ = ""
    sys.modules[name] = module
    exec(compile(_source(name), module.__file__, "exec"), module.__dict__)


def main() -> None:
    print(
        "[start] L4 exact response-fibre Krawczyk audit v1.2; "
        "frozen per-path radius schedule, no finite-error outcomes used...",
        flush=True,
    )
    _install("pasqal_two_atom_matched_fibre_test")
    _install("pasqal_two_atom_q2_prospective_ranking")
    runtime_file = globals().get("__file__", "<colab-notebook-cell>")
    namespace = {
        "__name__": "__main__",
        "__file__": runtime_file,
        "__package__": None,
    }
    exec(compile(_source("_kraw_main"), "<embedded:krawczyk_audit_v1_2>", "exec"), namespace)


if __name__ == "__main__":
    main()